const SRC = '/home/claude/RepairShop/src/RepairShop.Core/';

function excerpt(file, from, to) {      // фрагмент исходника от строки с from до строки с to (включительно)
  const lines = fs.readFileSync(SRC + file, 'utf8').split('\n');
  const a = lines.findIndex(l => l.includes(from));
  if (a < 0) throw new Error('нет ' + from);
  let b = a;
  while (b < lines.length && !lines[b].includes(to)) b++;
  const block = lines.slice(a, b + 1);
  const indent = Math.min.apply(null, block.filter(l => l.trim()).map(l => l.match(/^ */)[0].length));
  return block.map(l => l.slice(indent).replace(/\s+$/, '')).join('\n');
}
module.exports.excerpt = excerpt;

